function interpolate(template, vars = {}) {
    return String(template).replace(/\{(\w+)\}/g, (_, key) => vars[key] ?? '');
}

function resolveTextKey(keyOrText, vars = {}) {
    if (keyOrText && typeof keyOrText === 'object') {
        return [keyOrText.key || keyOrText.text || '', { ...vars, ...(keyOrText.vars || {}) }];
    }

    const raw = String(keyOrText ?? '');
    if (STRINGS.en[raw]) return [raw, vars];

    const alias = TEXT_ALIASES[raw];
    if (alias) return [alias, vars];

    for (const [pattern, resolver] of TEXT_PATTERNS) {
        const match = raw.match(pattern);
        if (match) {
            const [key, patternVars] = resolver(match);
            return [key, { ...patternVars, ...vars }];
        }
    }

    return [raw, vars];
}

