// Languages with complete string coverage (menu + all in-game text). Only these are
// offered in the language selector. fr/de/ja/zh still have only the ~15 menu strings
// translated, so selecting them would show a mostly-English game and make the toggle
// feel broken (it appeared to do nothing / only flip to German). Add a code here once
// that language's translations are finished. LANGUAGE_OPTIONS is kept full so
// getLanguageName can still resolve labels for legacy settings.
const SUPPORTED_LANGUAGES = ['en', 'es', 'fr', 'ru'];

export function getLanguageOptions() {
    return LANGUAGE_OPTIONS.filter(option => SUPPORTED_LANGUAGES.includes(option.code));
}

export function normalizeLanguageCode(language) {
    const value = String(language || 'en');
    const lower = value.toLowerCase();
    const legacy = {
        english: 'en',
        spanish: 'es',
        'español': 'es',
        french: 'fr',
        'français': 'fr',
        german: 'de',
        deutsch: 'de',
        japanese: 'ja',
        '日本語': 'ja',
        chinese: 'zh',
        '中文': 'zh',
        russian: 'ru',
        'русский': 'ru',
    };
    return LANGUAGE_OPTIONS.some(option => option.code === lower)
        ? lower
        : legacy[lower] || 'en';
}

